mapper.select:
WITH visit_stats AS (
	SELECT COUNT(*)::integer AS today_visit_count
	FROM visits v
	WHERE v.health_center_id = #{healthCenterId}
	  AND v.checked_in_at::date = #{targetDate}
),
waiting_stats AS (
	SELECT COUNT(*)::integer AS current_waiting_count
	FROM queue_tickets q
	WHERE q.health_center_id = #{healthCenterId}
	  AND q.issued_at::date = #{targetDate}
	  AND q.status = 'WAITING'
),
wait_stats AS (
	SELECT COALESCE(ROUND(AVG(EXTRACT(EPOCH FROM (q.called_at - q.issued_at)) / 60)), 0)::integer AS average_wait_minutes
	FROM queue_tickets q
	WHERE q.health_center_id = #{healthCenterId}
	  AND q.issued_at::date = #{targetDate}
	  AND q.called_at IS NOT NULL
),
reservation_stats AS (
	SELECT
		COUNT(*) FILTER (WHERE r.status != 'CANCELED') AS target_count,
		COUNT(*) FILTER (WHERE r.status = 'NO_SHOW') AS no_show_count
	FROM reservations r
	WHERE r.health_center_id = #{healthCenterId}
	  AND r.reserved_at::date = #{targetDate}
)
SELECT
	visit_stats.today_visit_count,
	waiting_stats.current_waiting_count,
	wait_stats.average_wait_minutes,
	CASE
		WHEN reservation_stats.target_count = 0 THEN 0.0
		ELSE ROUND((reservation_stats.no_show_count::numeric / reservation_stats.target_count::numeric) * 100, 1)
	END AS no_show_rate
FROM visit_stats
CROSS JOIN waiting_stats
CROSS JOIN wait_stats
CROSS JOIN reservation_stats
